messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- SCENE SETUP ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(-10, 5, 10);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- LIGHTS ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.1;
        dirLight.shadow.camera.far = 100;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        scene.add(dirLight);

        // --- ENVIRONMENT ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 50);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x228B22 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(200, 12);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishX = 40;
        const finishGeo = new THREE.PlaneGeometry(12, 2);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff }); // Checkerboard simplified
        const finish = new THREE.Mesh(finishGeo, finishMat);
        finish.rotation.x = -Math.PI / 2;
        finish.position.set(finishX, 0.01, 0);
        scene.add(finish);

        // Finish Line Posts
        const postGeo = new THREE.BoxGeometry(0.5, 5, 0.5);
        const postMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const post1 = new THREE.Mesh(postGeo, postMat);
        post1.position.set(finishX, 2.5, 6);
        scene.add(post1);
        const post2 = new THREE.Mesh(postGeo, postMat);
        post2.position.set(finishX, 2.5, -6);
        scene.add(post2);

        // Banner
        const bannerGeo = new THREE.PlaneGeometry(12, 3);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(finishX, 5, 0);
        scene.add(banner);

        // --- CAR CREATION ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2.5, 1, 4.5);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.7;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(2, 0.8, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.5, -0.5);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const wheelPositions = [
                { x: -1.2, z: 1.5 },
                { x: 1.2, z: 1.5 },
                { x: -1.2, z: -1.5 },
                { x: 1.2, z: -1.5 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        redCar.position.set(-50, 0, 3); // Start position, lane 1
        scene.add(redCar);

        const blueCar = createCar(0x0000ff);
        blueCar.position.set(-50, 0, -3); // Start position, lane 2
        scene.add(blueCar);

        // --- ANIMATION LOGIC ---
        const raceDistance = 100;
        const finishLineX = 40;
        let raceTime = 0;
        let lastTimestamp = 0;

        // Reset function
        function resetRace() {
            redCar.position.x = -50;
            blueCar.position.x = -50;
            raceTime = 0;
        }

        // Animation loop
        function animate(timestamp) {
            requestAnimationFrame(animate);

            if (!lastTimestamp) lastTimestamp = timestamp;
            const deltaTime = (timestamp - lastTimestamp) / 1000; // seconds
            lastTimestamp = timestamp;

            // Update race time
            raceTime += deltaTime;

            // --- RACING LOGIC ---
            // Blue car: Fast start, slows down slightly
            // Red car: Slow start, accelerates

            // Normalize progress 0 to 1 over the race duration
            // Race lasts about 6 seconds total
            const raceDuration = 6.0;
            const progress = Math.min(raceTime / raceDuration, 1.0);

            // Blue car trajectory (leads early)
            // Uses a curve that starts fast but slows
            const blueSpeed = 15 + Math.sin(raceTime * 0.5) * 2; // fluctuating speed
            blueCar.position.x = -50 + (blueSpeed * raceTime);

            // Red car trajectory (slower start, catches up)
            // Accelerates more aggressively
            const redSpeed = 10 + (raceTime * 3); // Linear acceleration
            redCar.position.x = -50 + (redSpeed * raceTime);

            // Ensure cars don't go backwards
            redCar.position.x = Math.max(-50, redCar.position.x);
            blueCar.position.x = Math.max(-50, blueCar.position.x);

            // Check for finish line crossing
            if (redCar.position.x >= finishLineX || blueCar.position.x >= finishLineX) {
                // Red car wins (it's programmed to cross slightly after or at same time)
                // Reset race
                resetRace();
            }

            // --- CAMERA LOGIC ---
            // Camera follows the midpoint between the two cars
            const midX = (redCar.position.x + blueCar.position.x) / 2;
            const midZ = (redCar.position.z + blueCar.position.z) / 2;

            // Smoothly interpolate camera position
            camera.position.x += (midX - 10 - camera.position.x) * 0.05;
            camera.position.y += (5 - camera.position.y) * 0.05;
            camera.position.z += (10 - camera.position.z) * 0.05;

            // Camera looks at the midpoint between the cars
            const lookTarget = new THREE.Vector3(midX, 0, midZ);
            camera.lookAt(lookTarget);

            // --- RENDER ---
            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate(0);
    </script>
</body>
</html>
```
